module stochastic_scheduling (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [7:0] s0, a0, b0,\n    input wire [7:0] s1, a1, b1,\n    input wire [7:0] s2, a2, b2,\n    input wire [7:0] s3, a3, b3,\n    input wire [7:0] s4, a4, b4,\n    input wire [7:0] s5, a5, b5,\n    input wire [7:0] s6, a6, b6,\n    input wire [7:0] s7, a7, b7,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] IDLE            = 4'd0;\n    localparam [3:0] START           = 4'd1;\n    localparam [3:0] COMPUTE_L       = 4'd2;\n    localparam [3:0] COMPUTE_J       = 4'd3;\n    localparam [3:0] NEXT_L          = 4'd4;\n    localparam [3:0] CALC_DP         = 4'd5;\n    localparam [3:0] NEXT_I          = 4'd6;\n    localparam [3:0] FIND_MAX        = 4'd7;\n    localparam [3:0] FIND_MAX_LOOP   = 4'd8;\n    localparam [3:0] DONE_STATE      = 4'd9;\n\n    // Internal registers\n    reg [3:0] state;\n    reg [3:0] i_idx;\n    reg [3:0] j_idx;\n    reg [7:0] L_val;\n    reg [31:0] sum;\n    reg [31:0] best_val;\n    reg [8:0] t_val;\n    reg [3:0] len_val;\n    reg [31:0] max_val;\n    reg [15:0] rec_val;\n    reg [63:0] product;\n\n    // Storage arrays\n    reg [7:0] s_reg [0:7];\n    reg [7:0] a_reg [0:7];\n    reg [7:0] b_reg [0:7];\n    reg [31:0] dp_reg [0:7];\n\n    integer idx;  // Loop variable\n\n    // Fixed-point reciprocal function (Q16.16)\n    function [15:0] compute_rec;\n        input [3:0] len;\n        begin\n            case (len)\n                4'd1:  compute_rec = 16'd65536;\n                4'd2:  compute_rec = 16'd32768;\n                4'd3:  compute_rec = 16'd21845;\n                4'd4:  compute_rec = 16'd16384;\n                4'd5:  compute_rec = 16'd13107;\n                4'd6:  compute_rec = 16'd10923;\n                4'd7:  compute_rec = 16'd9362;\n                4'd8:  compute_rec = 16'd8192;\n                4'd9:  compute_rec = 16'd7282;\n                4'd10: compute_rec = 16'd6554;\n                4'd11: compute_rec = 16'd5958;\n                4'd12: compute_rec = 16'd5461;\n                4'd13: compute_rec = 16'd5041;\n                4'd14: compute_rec = 16'd4681;\n                4'd15: compute_rec = 16'd4369;\n                4'd16: compute_rec = 16'd4096;\n                default: compute_rec = 16'd0;\n            endcase\n        end\n    endfunction\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            max_val <= 32'd0;\n\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                s_reg[idx] <= 8'd0;\n                a_reg[idx] <= 8'd0;\n                b_reg[idx] <= 8'd0;\n                dp_reg[idx] <= 32'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Load input data\n                        s_reg[0] <= s0; a_reg[0] <= a0; b_reg[0] <= b0;\n                        s_reg[1] <= s1; a_reg[1] <= a1; b_reg[1] <= b1;\n                        s_reg[2] <= s2; a_reg[2] <= a2; b_reg[2] <= b2;\n                        s_reg[3] <= s3; a_reg[3] <= a3; b_reg[3] <= b3;\n                        s_reg[4] <= s4; a_reg[4] <= a4; b_reg[4] <= b4;\n                        s_reg[5] <= s5; a_reg[5] <= a5; b_reg[5] <= b5;\n                        s_reg[6] <= s6; a_reg[6] <= a6; b_reg[6] <= b6;\n                        s_reg[7] <= s7; a_reg[7] <= a7; b_reg[7] <= b7;\n\n                        // Initialize DP array\n                        for (idx = 0; idx < 8; idx = idx + 1) begin\n                            dp_reg[idx] <= 32'd0;\n                        end\n\n                        // Start with i = n-1\n                        i_idx <= (n > 0) ? n - 4'd1 : 4'd0;\n                        state <= START;\n                    end\n                end\n\n                START: begin\n                    if (i_idx >= n) begin  // Check if all i processed\n                        state <= FIND_MAX;\n                    end else begin\n                        sum <= 32'd0;\n                        L_val <= a_reg[i_idx];\n                        state <= COMPUTE_L;\n                    end\n                end\n\n                COMPUTE_L: begin\n                    if (L_val > b_reg[i_idx]) begin\n                        // Compute DP[i] = 1 + (sum * rec)\n                        len_val <= b_reg[i_idx] - a_reg[i_idx] + 4'd1;\n                        rec_val <= compute_rec(len_val);\n                        state <= CALC_DP;\n                    end else begin\n                        t_val <= s_reg[i_idx] + L_val;\n                        best_val <= 32'd0;\n                        j_idx <= 4'd0;\n                        state <= COMPUTE_J;\n                    end\n                end\n\n                COMPUTE_J: begin\n                    if (j_idx >= n) begin\n                        // Add best_val to sum\n                        sum <= sum + best_val;\n                        L_val <= L_val + 8'd1;\n                        state <= COMPUTE_L;\n                    end else begin\n                        if (s_reg[j_idx] >= t_val && dp_reg[j_idx] > best_val) begin\n                            best_val <= dp_reg[j_idx];\n                        end\n                        j_idx <= j_idx + 4'd1;\n                        state <= COMPUTE_J;\n                    end\n                end\n\n                CALC_DP: begin\n                    // Compute: 32-bit sum (16.16) * 16-bit rec (16.16) -> 48-bit product\n                    product <= sum * rec_val;\n                    // Take upper 32 bits and add 1 (Q16.16: 1 = 65536)\n                    dp_reg[i_idx] <= 32'd65536 + product[47:16];\n                    // Move to next i\n                    i_idx <= i_idx - 4'd1;\n                    state <= START;\n                end\n\n                FIND_MAX: begin\n                    max_val <= 32'd0;\n                    i_idx <= 4'd0;\n                    state <= FIND_MAX_LOOP;\n                end\n\n                FIND_MAX_LOOP: begin\n                    if (i_idx >= n) begin\n                        result <= max_val;\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else begin\n                        if (dp_reg[i_idx] > max_val) begin\n                            max_val <= dp_reg[i_idx];\n                        end\n                        i_idx <= i_idx + 4'd1;\n                        state <= FIND_MAX_LOOP;\n                    end\n                end\n\n                DONE_STATE: begin\n                    if (!start) begin\n                        state <= IDLE;\n                        done <= 1'b0;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule